import sys

def main():
    n = int(sys.stdin.readline())
    sequence = [0]
    total = 0
    for _ in range(n):
        parts = sys.stdin.readline().split()
        t = int(parts[0])
        if t == 1:
            a, x = int(parts[1]), int(parts[2])
            for i in range(min(a, len(sequence))):
                total += x
                sequence[i] += x
        elif t == 2:
            k = int(parts[1])
            sequence.append(k)
            total += k
        elif t == 3:
            if len(sequence) > 1:
                total -= sequence[-1]
                sequence.pop()
        avg = total / len(sequence)
        print(f"{avg:.6f}")

if __name__ == "__main__":
    main()
